// Native Wobnimo generator. No browser code or runtime GLSL compiler is shipped.
// Usage: node scripts/sync-wobnimo-bundle.mjs [dist/wobnimo.js] [--check]
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';
import { translate } from './wobnimo/translate.mjs';

const app = join(dirname(fileURLToPath(import.meta.url)), '..');
const args = process.argv.slice(2);
const source = args.find(a => !a.startsWith('--')) ?? join(app, 'node_modules/wobnimo/dist/wobnimo.js');
const code = readFileSync(source, 'utf8');
// Fail closed on upstream changes, including newly introduced shader constructs.
if (createHash('sha256').update(code).digest('hex') !== '85443e0bd564e9e8428aced315346d80c304d647b8859bdb95b5203a2b5752ef') {
    throw new Error('Unrecognised wobnimo dist: review extraction and every translation rule before updating the hash.');
}
const license = readFileSync(join(dirname(source), '../LICENSE'), 'utf8').trim();
const header = `// Generated by scripts/sync-wobnimo-bundle.mjs; do not edit.\n/*\n${license}\n*/\n`;
const tail = code.match(/Fe\(\);export\{[^}]+\};\s*$/);
if (!tail) throw new Error('Wobnimo registration/export tail changed');
// The shared browser scheduler is instantiated eagerly upstream; omit that unused instance.
const base = code.slice(0, tail.index).replace('Ae=new $e', 'Ae=/* @__PURE__ */new $e');
async function bundle(exports, input = base) {
    const result = await build({ stdin: { contents: `${input}\nexport {${exports}};`, resolveDir: app },
        bundle: true, write: false, format: 'esm', platform: 'neutral', treeShaking: true, minify: true });
    return result.outputFiles[0].text;
}
// Behaviour and rig precede the browser renderer. Exclude all DOM and character
// declarations before tree shaking (some unused specs have eager flatMap calls).
const rendererStart = base.indexOf('var it=48,me=128');
if (rendererStart < 0) throw new Error('Renderer boundary changed');
const engine = await bundle('U as Brain,W as Rig,X as Fx,J as random', base.slice(0, rendererStart));
if (/\b(document|window|customElements|requestAnimationFrame|eval|HTMLElement|IntersectionObserver|matchMedia)\b/.test(engine)) {
    throw new Error('Browser dependency survived headless extraction');
}
// Build-only import: this is never evaluated by Hermes.
const compiler = await bundle('Me as compile,D0 as characters');
const { compile, characters } = await import(`data:text/javascript;base64,${Buffer.from(compiler).toString('base64')}`);
const catalog = readFileSync(join(app, 'src/lib/veyCharacterChoice.ts'), 'utf8')
    .match(/export const WOBNIMO_CHARACTERS = \[([\s\S]*?)\] as const;/)?.[1];
if (!catalog) throw new Error('Character catalog shape changed');
const ids = [...catalog.matchAll(/'([a-z]+)'/g)].map(m => m[1]);
if (ids.length !== 20 || new Set(ids).size !== 20) throw new Error('Expected 20 unique mascots');
const programs = {};
const data = {};
for (const id of ids) {
    const spec = characters.find(c => c.id === id);
    if (!spec) throw new Error(`Missing character: ${id}`);
    const { fragment, bones, acting, anchors, albedo } = compile(spec);
    programs[id] = translate(fragment);
    const { motion, frame, bound, glowPool, fx } = spec;
    data[id] = { spec: { motion, frame, bound, glowPool, fx }, bones, acting, anchors, albedo: Array.from(albedo) };
}
const outputs = {
    'wobnimoEngine.generated.js': header + engine,
    'wobnimoPrograms.generated.ts': header + `export const WOBNIMO_PROGRAMS = ${JSON.stringify(programs)};\n`,
    'wobnimoData.generated.ts': header + `export const WOBNIMO_DATA = ${JSON.stringify(data)};\n`,
};
for (const [name, content] of Object.entries(outputs)) {
    const target = join(app, 'src/lib', name);
    if (args.includes('--check')) {
        if (readFileSync(target, 'utf8') !== content) throw new Error(`${name} is stale; run the generator`);
    } else {
        writeFileSync(target, content);
        console.log(`wrote ${name} (${(content.length / 1024).toFixed(0)} KiB)`);
    }
}
